trim.if:
SELECT d.id, 'DISH' AS product_type, m.id AS merchant_id, m.name AS merchant_name, dc.id AS category_id, dc.name AS category_name, d.name, d.price, d.image_path, d.description, d.sales_count, ( SELECT JSON_ARRAYAGG(cn.nutrition_tag) FROM category_nutrition cn WHERE cn.category_id = d.category_id ) AS nutrition_tags_json FROM dish d JOIN merchant m ON m.id = d.merchant_id JOIN dish_category dc ON dc.id = d.category_id WHERE d.status = 'ON_SALE' AND m.business_status = 1
AND d.merchant_id = #{merchantId}
AND d.category_id = #{categoryId}
AND ( d.name LIKE CONCAT('%', #{keyword}, '%') OR d.description LIKE CONCAT('%', #{keyword}, '%') OR dc.name LIKE CONCAT('%', #{keyword}, '%') OR EXISTS ( SELECT 1 FROM category_nutrition cn WHERE cn.category_id = d.category_id AND cn.nutrition_tag LIKE CONCAT('%', #{keyword}, '%') ) )
UNION ALL

